    ei_class = data[4]
    if ei_class not in (1,2):
        raise ParseError(f"Unknown bitness: {ei_class}")
    ei_data = data[5]
    if ei_data not in (1,2):
        raise ParseError(f"Unknown endianness: {ei_data}")
    is64 = (ei_class == 2)
    le = (ei_data == 1)
